Here is the commit message:
net: wan/fsl_ucc_hdlc: Fix dma_free_coherent() in
 uhdlc_memclean()

The priv->rx_buffer and priv->tx_buffer are alloc'd together as
contiguous buffers in uhdlc_init() but freed as two buffers in
uhdlc_memclean().

Change the cleanup to only call dma_free_coherent() once on the whole
buffer.

Reviewed-by: Christophe Leroy (CS GROUP) <chleroy@kernel.org>
Fixes: c19b6d246a35 ("drivers/net: support hdlc function for QE-UCC")
Cc: <stable@vger.kernel.org>
Signed-off-by: Thomas Fourier <fourier.thomas@gmail.com>
Link: https://patch.msgid.link/20260206085334.21195-2-fourier.thomas@gmail.com
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The uhdlc_memclean() function incorrectly frees the rx and tx DMA buffers separately, but they were allocated together as a single contiguous block in uhdlc_init(). This mismatch causes the dma_free_coherent() calls to use incorrect sizes and potentially free the same memory region multiple times, leading to memory corruption or double-free.

Here is the patch:

 static void uhdlc_memclean(struct ucc_hdlc_private *priv)
 {
 	qe_muram_free(ioread16be(&priv->ucc_pram->riptr));
 	qe_muram_free(ioread16be(&priv->ucc_pram->tiptr));

 	if (priv->rx_bd_base) {
 		dma_free_coherent(priv->dev,
 				  RX_BD_RING_LEN * sizeof(struct qe_bd),
 				  priv->rx_bd_base, priv->dma_rx_bd);

 		priv->rx_bd_base = NULL;
 		priv->dma_rx_bd = 0;
 	}

 	if (priv->tx_bd_base) {
 		dma_free_coherent(priv->dev,
 				  TX_BD_RING_LEN * sizeof(struct qe_bd),
 				  priv->tx_bd_base, priv->dma_tx_bd);

 		priv->tx_bd_base = NULL;
 		priv->dma_tx_bd = 0;
 	}

 	if (priv->ucc_pram) {
 		qe_muram_free(priv->ucc_pram_offset);
 		priv->ucc_pram = NULL;
 		priv->ucc_pram_offset = 0;
 	 }

 	kfree(priv->rx_skbuff);
 	priv->rx_skbuff = NULL;

 	kfree(priv->tx_skbuff);
 	priv->tx_skbuff = NULL;

 	if (priv->uf_regs) {
 		iounmap(priv->uf_regs);
 		priv->uf_regs = NULL;
 	}

 	if (priv->uccf) {
 		ucc_fast_free(priv->uccf);
 		priv->uccf = NULL;
 	}

 	if (priv->rx_buffer) {
 		dma_free_coherent(priv->dev,
-				  RX_BD_RING_LEN * MAX_RX_BUF_LENGTH,
+				  (RX_BD_RING_LEN + TX_BD_RING_LEN) * MAX_RX_BUF_LENGTH,
 				  priv->rx_buffer, priv->dma_rx_addr);
 		priv->rx_buffer = NULL;
 		priv->dma_rx_addr = 0;
-	}

-	if (priv->tx_buffer) {
-		dma_free_coherent(priv->dev,
-				  TX_BD_RING_LEN * MAX_RX_BUF_LENGTH,
-				  priv->tx_buffer, priv->dma_tx_addr);
 		priv->tx_buffer = NULL;
 		priv->dma_tx_addr = 0;
+
 	}
 }



